    letter-spacing: 0.12em;
    margin-bottom: 14px;
  }
  .kicker {
    font-family: 'IBM Plex Mono', monospace;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    margin-bottom: 12px;
    color: var(--grey);
  }
  .cell.red .kicker, .cell.blue .kicker { color: rgba(255,255,255,0.75); }
  .cell.yellow .kicker { color: #6b5900; }
  p { font-size: 1rem; }
  .big { font-size: 1.15rem; font-weight: 500; }
  .fact {
    font-family: 'IBM Plex Mono', monospace;
    font-size: 0.92rem;
    line-height: 1.7;
  }
  .fact b { font-weight: 500; }
  .divider { height: 4px; background: var(--black); width: 64px; margin: 16px 0; }
  .cell.red .divider, .cell.blue .divider { background: var(--white); }
  .cell.yellow .divider { background: var(--black); }

  .painting {
    display: grid;
    grid-template-columns: 5fr 3fr;
    grid-template-rows: 6fr 4fr;
    gap: 14px;
    background: var(--black);
    padding: 14px;
    aspect-ratio: 1 / 1;
  }
  .painting .p { background: var(--white); }
  .painting .p.red { background: var(--red); grid-column: 2; grid-row: 1; }
  .painting .p.blue { background: var(--blue); grid-column: 1; grid-row: 2; }
  .painting .p.yellow { background: var(--yellow); grid-column: 2; grid-row: 2; }

