    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.9rem;
    text-decoration: none;
    color: var(--black);
    border: 3px solid var(--black);
    padding: 12px 22px;
    background: var(--white);
  }
  a.read:hover { background: var(--black); color: var(--white); }
  .cell.red a.read { color: var(--white); border-color: var(--white); background: transparent; }
  .cell.red a.read:hover { background: var(--white); color: var(--red); }

